const DB='MAGHRABY_STORE_FRESH_FINAL',VER=3;
const ACCOUNTS=[['drawer','الدرج'],['wallet','المحفظة الإلكترونية'],['instapay','InstaPay']];
const stores=['products','sales','repairs','cash','expenses','purchases','customers','staff','invoices','days','audit','settings','transfers','returns','repairTypes','discountCodes','accounts','stockMoves'];
let db,state={page:'sale',cat:'',cart:[],discount:0,cartNote:'',saleCustomer:'',saleAccount:'drawer',discountCode:'',lastInvoice:null,q:'',globalQ:''};
const NAV=[
['dashboard','⌂','لوحة التحكم'],['sale','▣','المبيعات والكاشير'],['repair','⌁','الصيانة والمتابعة'],
['inventory','◇','المخزون والمنتجات'],['purchases','＋','المشتريات والتوريد'],['customers','◉','العملاء'],['accounts','◌','حسابات العملاء'],
['cash','₤','الخزنة والحركات'],['expenses','−','مصروفات المحل'],['staff','⚒','الفنيون والسلف'],
['needs','≡','الاحتياجات'],['discounts','%','أكواد الخصم'],['returns','↶','المرتجعات'],['reports','▥','الربح والتقارير'],['invoices','▤','الفواتير'],['settings','⚙','الإعدادات']
];
const seed=[];
const $=id=>document.getElementById(id),uid=()=>crypto.randomUUID(),now=()=>new Date().toISOString(),today=()=>now().slice(0,10);
const money=n=>new Intl.NumberFormat('ar-EG',{maximumFractionDigits:0}).format(Number(n)||0)+' ج';
const accountName=a=>(ACCOUNTS.find(x=>x[0]===a)||ACCOUNTS[0])[1];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function normalizeCash(x){return {...x,account:x.account||'drawer'};}
async function cashAll(){return (await req('cash')).map(normalizeCash)}
async function dayRecord(date){return (await req('days')).find(x=>x.date===date)}
async function openingBalance(date,account){let days=await req('days');let prev=days.filter(x=>x.date<date).sort((a,b)=>b.date.localeCompare(a.date))[0];if(prev){if(account==='drawer')return Number(prev.drawerCounted??prev.counted??0);return Number(prev[account+'Counted']??0)}let settings=await req('settings');let init=settings.find(x=>x.id==='finance');return Number(init?.[account+'Opening']??0)}
async function balanceFor(date,account){let c=(await cashAll()).filter(x=>x.date.slice(0,10)===date&&x.account===account);let opening=await openingBalance(date,account),inc=c.filter(x=>x.type==='in').reduce((a,x)=>a+Number(x.amount||0),0),out=c.filter(x=>x.type==='out').reduce((a,x)=>a+Number(x.amount||0),0);return {opening,inc,out,expected:opening+inc-out}}
function accountOptions(selected='drawer'){return ACCOUNTS.map(([id,n])=>`<option value="${id}" ${selected===id?'selected':''}>${n}</option>`).join('')}
function whatsapp(phone,text){let p=String(phone||'').replace(/[^0-9]/g,'');if(p.startsWith('0'))p='20'+p.slice(1);if(!p)return toast('رقم العميل غير صالح للواتساب');window.open('https://wa.me/'+p+'?text='+encodeURIComponent(text),'_blank','noopener');}
const val=id=>$(id)?.value?.trim()||'';
function req(s){return new Promise((res,rej)=>{let q=db.transaction(s).objectStore(s).getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)})}
function put(s,x){return new Promise((res,rej)=>{let q=db.transaction(s,'readwrite').objectStore(s).put(x);q.onsuccess=()=>res(x);q.onerror=()=>rej(q.error)})}
async function boot(){await new Promise((res,rej)=>{let r=indexedDB.open(DB,VER);r.onupgradeneeded=()=>{db=r.result;stores.forEach(s=>{if(!db.objectStoreNames.contains(s))db.createObjectStore(s,{keyPath:'id'})})};r.onsuccess=()=>{db=r.result;res()};r.onerror=()=>rej(r.error)});bind();clock();render();autoBackupSnapshot().catch(()=>{})}
function bind(){
  $('menu').onclick=()=> $('sidebar').classList.toggle('open');
  $('backup').onclick=backup;
  $('closeToday').onclick=closeDay;
  let gs=$('globalSearch');
  if(gs){
    gs.onkeydown=async e=>{
      if(e.key==='Enter'){
        let q=gs.value.trim();
        if(!q)return;
        let [ps,cs]=await Promise.all([req('products'),req('customers')]);
        let p=ps.find(x=>x.name.includes(q)||String(x.barcode||'')===q);
        let c=cs.find(x=>x.name.includes(q)||String(x.phone||'').includes(q));
        if(p){state.page='inventory';state.q=q}else if(c){state.page='customers';state.q=q}else{state.page='sale';state.q=q}
        render();
      }
    };
    window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();gs.focus()}});
  }
  document.addEventListener('click',e=>{
    let b=e.target.closest('[data-page]');
    if(b){state.page=b.dataset.page;state.cat='';render();$('sidebar').classList.remove('open')}
  });
}
function clock(){setInterval(()=>{let d=new Date();$('date').textContent=d.toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('time').textContent=d.toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit',second:'2-digit'})},500)}
function nav(){ $('nav').innerHTML=NAV.map(n=>`<button class="nav-item ${state.page===n[0]?'active':''}" data-page="${n[0]}"><span class="nav-icon">${n[1]}</span><span class="nav-label">${n[2]}</span><span class="nav-arrow">‹</span></button>`).join('');$('title').textContent=(NAV.find(n=>n[0]===state.page)||NAV[0])[2]}
async function render(){nav();let v=$('view');({dashboard,sale,repair,inventory,purchases,customers,accounts,cash,expenses,staff,needs,discounts,returns,reports,invoices,settings}[state.page]||dashboard)(v)}
function stat(label,n,sub='',kind='money'){let shown=typeof n==='number'?(kind==='count'?Number(n).toLocaleString('ar-EG')+' '+sub:money(n)):n;return `<div class="card stat"><div class="label">${label}</div><div class="num">${shown}</div>${kind==='count'?'':`<div class="sub">${sub}</div>`}</div>`}
async function dashboard(v){let [s,r,e,c,p]=await Promise.all([req('sales'),req('repairs'),req('expenses'),cashAll(),req('products')]),d=today(),sd=s.filter(x=>x.date.slice(0,10)===d),ed=e.filter(x=>x.date.slice(0,10)===d),pending=r.filter(x=>x.status!=='تم التسليم'),low=p.filter(x=>x.type!=='service'&&x.stock<=x.min&&x.min>0),drawer=await balanceFor(d,'drawer'),wallet=await balanceFor(d,'wallet'),instapay=await balanceFor(d,'instapay'),cogs=sd.reduce((a,x)=>a+x.items.reduce((z,i)=>z+i.cost*i.qty,0),0),salesTotal=sd.reduce((a,x)=>a+(x.items.some(i=>i.repairId)?0:x.total),0),profit=salesTotal-cogs-ed.reduce((a,x)=>a+x.amount,0);
let rawCash=await cashAll();let todayCash=rawCash.filter(x=>x.date.slice(0,10)===d&&!x.transfer);let inc=todayCash.filter(x=>x.type==='in').reduce((a,x)=>a+Number(x.amount||0),0),out=todayCash.filter(x=>x.type==='out').reduce((a,x)=>a+Number(x.amount||0),0);
v.innerHTML=`<div class="grid stats">${stat('مبيعات اليوم',salesTotal,'بعد الخصومات')}${stat('دخل الخزنة',inc,'كل حركات الداخل')}${stat('خرج الخزنة',out,'كل حركات الخارج')}${stat('المتوقع في الدرج',drawer.expected,'رصيد أمس + الداخل − الخارج')}${stat('المحفظة',wallet.expected,'رصيد جارٍ')}${stat('InstaPay',instapay.expected,'رصيد جارٍ')}${stat('ربح تقريبي',profit,'مبيعات − تكلفة − مصروفات')}${stat('أجهزة معلقة',pending.length,'جهاز','count')}</div>
<div class="hero card"><div><span class="eyebrow">MAGHRABY STORE • مركز التشغيل</span><h2>جاهز تبدأ شغل اليوم؟</h2><p>أضف المنتجات والخدمات أولًا، وبعدها النظام هيبني لك المبيعات والمخزون والتقارير تلقائيًا.</p></div><button class="btn primary hero-btn" data-page="inventory">＋ ابدأ بإضافة أول منتج</button></div><div class="section"><h2>مركز العمل</h2></div><div class="grid quick"><button data-page="sale">🛒<b>بيع جديد</b><small>سلة + خصم + ملاحظات + فاتورة</small></button><button data-page="repair">🔧<b>استلام صيانة</b><small>الجهاز والعطل والمدة والحالة</small></button><button data-page="cash">💵<b>حركة خزنة</b><small>دخل / خرج / سلفة / مصروف</small></button><button data-page="purchases">📦<b>شراء بضاعة</b><small>يزود المخزون ويحسب التكلفة</small></button><button data-page="reports">🔒<b>إقفال اليوم</b><small>عد الدرج واعرف الفرق</small></button></div>
<div class="grid two"><div><div class="section"><h2>⚠ يحتاج انتباه</h2></div><div class="card">${low.length?low.map(p=>`<div class="kpi"><span>📦 ${p.name}<small> — الموجود ${p.stock}</small></span><b class="negative">اطلب الآن</b></div>`).join(''):'<div class="empty">المخزون الأساسي جيد 🎉</div>'}</div></div><div><div class="section"><h2>🔧 الصيانة</h2></div><div class="card">${pending.slice(0,5).map(r=>`<div class="kpi"><span><b>${r.customer}</b> — ${r.device}<small> ${r.fault}</small></span><b class="negative">${Math.floor((Date.now()-new Date(r.date))/86400000)} يوم</b></div>`).join('')||'<div class="empty">لا توجد أجهزة معلقة</div>'}</div></div></div>`}
async function sale(v){let [ps,cs]=await Promise.all([req('products'),req('customers')]);let cats=[...new Set(ps.map(p=>p.cat).filter(Boolean))];let q=(state.q||'').toLowerCase();let arr=ps.filter(p=>p.active!==false&&(!state.cat||p.cat===state.cat)&&(p.name.toLowerCase().includes(q)||String(p.barcode||'').toLowerCase().includes(q)));v.innerHTML=`
<div class="page-head"><div><span class="eyebrow">POS • MAGHRABY STORE</span><h2>المبيعات والكاشير</h2><p>بيع أسرع، عدد أقل من الضغطات، وحركة مالية محفوظة تلقائيًا.</p></div><div class="head-actions"><button class="btn ghost" onclick="clearCart()">مسح السلة</button><button class="btn primary" onclick="customerNew()">＋ عميل جديد</button></div></div>
<div class="pos-layout"><section class="card pos-products"><div class="toolbar"><div class="search large"><span>⌕</span><input placeholder="ابحث بالاسم أو القسم..." value="${esc(state.q||'')}" oninput="state.q=this.value;render()"></div><div class="chips"><button class="chip ${!state.cat?'active':''}" onclick="state.cat='';render()">الكل</button>${cats.map(c=>`<button class="chip ${state.cat===c?'active':''}" onclick="state.cat='${esc(c)}';render()">${esc(c)}</button>`).join('')}</div></div><div class="product-grid">${arr.map(p=>`<button class="product" onclick="add('${p.id}')"><div class="pic">${p.image?`<img src="${p.image}" alt="">`:`<span>${p.emoji||'📦'}</span>`}</div><span class="stock ${p.stock<=p.min&&p.type!=='service'?'danger':''}">${p.type==='service'?'خدمة':'متاح '+p.stock}</span><div class="pi"><b>${esc(p.name)}</b><small>${esc(p.cat||'بدون قسم')}</small><strong>${money(p.price)}</strong></div></button>`).join('')||`<div class="empty-state"><div class="empty-icon">📦</div><h2>لسه مفيش منتجات</h2><p>أضف منتجاتك من المخزون، وهتظهر هنا تلقائيًا في شاشة الكاشير.</p><button class="btn primary" onclick="state.page='inventory';render()">إضافة أول منتج</button></div>`}</div></section>
<section class="card cart pos-cart"><div class="cart-head"><div><span class="eyebrow">CURRENT ORDER</span><h2>السلة</h2></div><div class="cart-head-actions"><span class="cart-count">${state.cart.reduce((a,x)=>a+x.qty,0)} صنف</span><button class="btn red small" type="button" onclick="clearCart()" ${state.cart.length?'':'disabled'}>تفريغ السلة</button></div></div>
<div class="form compact"><label>العميل<select id="saleCustomer" onchange="state.saleCustomer=this.value"><option value="">عميل نقدي / بدون تسجيل</option>${cs.map(c=>`<option value="${c.id}" ${state.saleCustomer===c.id?'selected':''}>${esc(c.name)}${c.phone?' • '+esc(c.phone):''}</option>`).join('')}</select></label><label>الحساب<select id="saleAccount" onchange="state.saleAccount=this.value">${accountOptions(state.saleAccount)}</select></label></div>
<div class="cart-items">${cartHTML()}</div><div class="note"><label>ملاحظة الفاتورة<textarea id="cartNote" oninput="state.cartNote=this.value" placeholder="ملاحظة للفاتورة أو التسليم...">${esc(state.cartNote)}</textarea></label></div>
<div class="total"><div class="sum"><span>الإجمالي</span><b>${money(sub())}</b></div><div class="sum"><span>الخصم</span><b class="discount-value">− ${money(state.discount)}</b></div><div class="sum grand"><span>المطلوب</span><span>${money(grand())}</span></div></div><div class="actions sale-actions"><button class="btn orange" onclick="discount()">خصم</button><button class="btn primary" onclick="saveSale()">حفظ الفاتورة</button></div></section></div>`}
function cartHTML(){if(!state.cart.length)return'<div class="empty">ابدأ باختيار منتج من اليمين</div>';return state.cart.map((x,i)=>`<div class="cart-row"><div class="cart-item-main"><div><b>${esc(x.name)}</b><br><small>${money(x.price)} × ${x.qty}</small></div><button class="icon-btn danger" type="button" title="حذف من السلة" onclick="removeCartItem(${i})">×</button></div><div class="qty"><button onclick="changeQty(${i},-1)">−</button>${x.qty}<button onclick="changeQty(${i},1)">+</button></div><b>${money(x.price*x.qty)}</b></div>`).join('')}
function sub(){return state.cart.reduce((a,x)=>a+x.price*x.qty,0)}function grand(){return Math.max(0,sub()-state.discount)}
async function add(id){let p=(await req('products')).find(x=>x.id===id&&x.active!==false);if(!p)return;if(p.type!=='service'){let x=state.cart.find(x=>x.id===id);let next=(x?.qty||0)+1;if(next>Number(p.stock||0))return toast('الكمية المطلوبة أكبر من المخزون');x?x.qty=next:state.cart.push({id:p.id,name:p.name,price:p.price,cost:p.cost,qty:1})}else{let x=state.cart.find(x=>x.id===id);x?x.qty++:state.cart.push({id:p.id,name:p.name,price:p.price,cost:p.cost,qty:1})}await render()}
async function changeQty(i,d){let item=state.cart[i];if(!item)return;if(d>0){let p=(await req('products')).find(x=>x.id===item.id);if(p&&p.type!=='service'&&item.qty+1>Number(p.stock||0))return toast('لا توجد كمية إضافية في المخزون')}item.qty+=d;if(item.qty<1)state.cart.splice(i,1);await render()}async function removeCartItem(i){if(!state.cart[i])return;state.cart.splice(i,1);if(!state.cart.length){state.discount=0;state.cartNote=''}await render();toast('تم حذف الصنف من السلة')}async function clearCart(){if(!state.cart.length)return;state.cart=[];state.discount=0;state.discountCode='';state.cartNote='';await render();toast('تم تفريغ السلة')}
function discount(){modal('الخصم والكود',`<div class="actions">${[5,10,15,20].map(p=>`<button class="btn orange" onclick="applyDiscount(${p})">${p}%</button>`).join('')}</div><div class="form" style="margin-top:12px"><label>خصم بمبلغ<input id="dc" type="number"></label><label>كود خصم<input id="discountCodeInput" placeholder="MAGHRABY10"></label></div><div class="actions" style="margin-top:10px"><button class="btn mint" onclick="applyDiscountAmount()">تطبيق المبلغ</button><button class="btn primary" onclick="applyDiscountCode()">تطبيق الكود</button></div>`)}
function applyDiscountAmount(){state.discount=Math.min(sub(),Number(val('dc'))||0);state.discountCode='';closeModal();render()}
async function applyDiscountCode(){let code=val('discountCodeInput').toUpperCase();if(!code)return toast('اكتب كود الخصم');let x=(await req('discountCodes')).find(x=>x.code===code&&x.active!==false);if(!x)return toast('كود الخصم غير صالح');let d=today();if(x.start&&d<x.start)return toast('الكود لم يبدأ بعد');if(x.end&&d>x.end)return toast('انتهت صلاحية الكود');if(x.maxUses&&Number(x.used||0)>=Number(x.maxUses))return toast('الكود وصل للحد الأقصى للاستخدام');let amount=x.kind==='percent'?Math.round(sub()*Number(x.value)/100):Number(x.value)||0;state.discount=Math.min(sub(),amount);state.discountCode=x.code;closeModal();render();toast('تم تطبيق كود الخصم')}
function applyDiscount(p){state.discount=Math.round(sub()*p/100);state.discountCode='';closeModal();render()}
async function saveSale(){
if(!state.cart.length)return toast('السلة فاضية');
const customer=(await req('customers')).find(c=>c.id===state.saleCustomer),cartSnapshot=state.cart.map(i=>({...i})),x={id:uid(),date:now(),items:cartSnapshot,subtotal:sub(),discount:state.discount,total:grand(),note:state.cartNote,account:state.saleAccount,customerId:customer?.id||'',customerName:customer?.name||'',customerPhone:customer?.phone||'',discountCode:state.discountCode||''};
const ps=await req('products'),repairRows=await req('repairs'),discountRows=await req('discountCodes');for(const i of cartSnapshot){if(i.repairId)continue;const p=ps.find(p=>p.id===i.id);if(!p||p.active===false)return toast('أحد المنتجات لم يعد متاحًا');if(p.type!=='service'&&i.qty>Number(p.stock||0))return toast(`الكمية غير متاحة: ${p.name}`)}
const invoice={id:uid(),date:x.date,type:'بيع',total:x.total,ref:x.id,note:x.note,account:x.account,customerId:x.customerId,customerName:x.customerName,discount:x.discount,discountCode:x.discountCode},cash={id:uid(),date:x.date,type:'in',amount:x.total,account:x.account,reason:'بيع',ref:x.id,note:x.note};
try{const tx=db.transaction(['sales','invoices','cash','products','repairs','audit','discountCodes','stockMoves'],'readwrite'),putx=(st,o)=>tx.objectStore(st).put(o);putx('sales',x);putx('invoices',invoice);putx('cash',cash);putx('audit',{id:uid(),date:x.date,action:'بيع',data:x});
for(const i of cartSnapshot){if(i.repairId){const rr=repairRows.find(z=>z.id===i.repairId);if(rr){rr.status='تم التسليم';rr.deliveredAt=x.date;rr.paymentRecorded=true;rr.pendingDelivery=false;rr.account=x.account;putx('repairs',rr)}continue}const p=ps.find(p=>p.id===i.id);if(p&&p.type!=='service'){p.stock=Math.max(0,Number(p.stock||0)-i.qty);putx('products',p);putx('stockMoves',{id:uid(),date:x.date,productId:p.id,product:p.name,type:'sale',qty:-i.qty,ref:x.id,note:'بيع'})}}
if(x.discountCode){const d=discountRows.find(z=>z.code===x.discountCode);if(d){d.used=Number(d.used||0)+1;putx('discountCodes',d)}}
await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error||new Error('sale transaction failed'));tx.onabort=()=>rej(tx.error||new Error('sale aborted'))});state.lastInvoice=x;state.cart=[];state.discount=0;state.discountCode='';state.cartNote='';state.saleAccount='drawer';state.saleCustomer='';await render();toast('تم حفظ الفاتورة وتفريغ السلة بنجاح')}catch(e){console.error(e);toast('لم يتم حفظ الفاتورة: تم إلغاء العملية بالكامل')}}

async function repair(v){let rs=await req('repairs');let groups={new:rs.filter(r=>r.status==='تحت الفحص'),wait:rs.filter(r=>r.status==='بانتظار العميل'),fixed:rs.filter(r=>r.status==='تم الإصلاح'),rejected:rs.filter(r=>r.status==='رفض'),done:rs.filter(r=>r.status==='تم التسليم')};const col=(title,a,action='')=>`<div class="stage"><h3>${title} (${a.length})</h3>${a.map(r=>`<div class="job"><b>${r.customer} • ${r.device}</b><small>${r.fault}</small><small>${r.phone||'بدون هاتف'}</small><small class="repair-date">📅 الاستلام: ${new Date(r.date).toLocaleDateString('ar-EG')} — ${new Date(r.date).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small><div class="age">منذ ${Math.floor((Date.now()-new Date(r.date))/86400000)} يوم</div>${r.status!=='تم التسليم'?`<button class="btn mint" style="margin-top:8px" onclick="repairAction('${r.id}')">فتح الملف</button>`:''}</div>`).join('')||'<div class="empty">فارغ</div>'}</div>`;v.innerHTML=`<div class="section"><h2>لوحة الصيانة — بدون دفاتر</h2><button class="btn primary" onclick="newRepair()">＋ استلام جهاز</button></div><div class="pipeline repair-pipeline">${col('استلام / فحص',groups.new)}${col('بانتظار العميل',groups.wait)}${col('تم الإصلاح',groups.fixed)}${col('رفض',groups.rejected)}${col('تم التسليم',groups.done)}</div>`}
async function newRepair(){modal('استلام جهاز',`<div class="form"><label>اسم العميل<input id="rc"></label><label>الهاتف<input id="rp"></label><label>نوع الجهاز<select id="rd"><option>PS5</option><option>PS4</option><option>PS4 Pro</option><option>PS3</option><option>Xbox</option><option>دراع</option><option>يد تحكم أخرى</option><option>أخرى</option></select></label><label>نوع الصيانة<select id="rtype"><option value="">بدون تحديد</option></select></label><label>العطل<input id="rf" placeholder="HDMI / Power / بوردة..."></label><label>Serial Number<input id="rsn" placeholder="اختياري"></label><label>موعد التسليم المتوقع<input id="red" type="datetime-local"></label><label>السعر المبدئي<input id="ramount" type="number"></label><label>الفني المسؤول<input id="rtech" placeholder="اسم الفني"></label><label>الملحقات المستلمة<input id="racc" placeholder="يد تحكم، HDMI، كابل كهرباء..."></label><label class="full">ملاحظات الاستلام<textarea id="rn" placeholder="حالة الجهاز، خدوش، ملحقات، أي شيء مهم..."></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveRepair()">حفظ الاستلام</button>`);let types=await req('repairTypes');$('rtype').innerHTML='<option value="">بدون تحديد</option>'+types.filter(x=>x.active!==false).map(x=>`<option value="${x.id}" data-price="${x.price}">${esc(x.name)} • ${money(x.price)}</option>`).join('');$('rtype').onchange=()=>{let o=$('rtype').selectedOptions[0];$('ramount').value=o?.dataset?.price||''}}
async function saveRepair(){try{let all=await req('repairs');let code='REP-'+new Date().getFullYear()+'-'+String(all.length+1).padStart(4,'0');let x={id:uid(),code,date:now(),customer:val('rc'),customerId:'',phone:val('rp'),device:val('rd'),fault:val('rf'),serial:val('rsn'),expectedDelivery:val('red'),repairTypeId:val('rtype'),repairTypeName:($('rtype')?.selectedOptions?.[0]?.textContent||'').split(' • ')[0],technician:val('rtech'),accessories:val('racc'),note:val('rn'),status:'تحت الفحص',decision:'',account:'drawer',amount:Number(val('ramount'))||0,paymentRecorded:false,parts:[],partsCost:0};if(!x.customer||!x.fault)return toast('الاسم والعطل مطلوبان');let cust=(await req('customers')).find(c=>c.name===x.customer&&String(c.phone||'')===String(x.phone||''));x.customerId=cust?.id||'';await put('repairs',x);await log('استلام صيانة',x);closeModal();toast('تم حفظ استلام الصيانة بنجاح');await render()}catch(e){console.error(e);toast('تعذر حفظ الاستلام، حاول مرة أخرى')}}
async function repairAction(id){let r=(await req('repairs')).find(x=>x.id===id);if(!r)return;let qrText=encodeURIComponent('MAGHRABY STORE | '+(r.code||'')+' | '+(r.customer||'')+' | '+(r.device||''));modal('ملف الصيانة',`<div class="repair-modal-head"><div class="repair-id">${esc(r.code||'REP-'+r.id.slice(0,6).toUpperCase())}</div><div><b>${esc(r.customer)}</b><p>${esc(r.device)} • ${esc(r.fault)}</p><small>📅 الاستلام: ${new Date(r.date).toLocaleString('ar-EG')}</small></div></div><div class="grid two"><div class="card"><div class="kpi"><span>الهاتف</span><b>${esc(r.phone||'—')}</b></div><div class="kpi"><span>Serial Number</span><b>${esc(r.serial||'—')}</b></div><div class="kpi"><span>موعد التسليم المتوقع</span><b>${r.expectedDelivery?new Date(r.expectedDelivery).toLocaleString('ar-EG'):'غير محدد'}</b></div><div class="kpi"><span>الفني</span><b>${esc(r.technician||'—')}</b></div><div class="kpi"><span>الملحقات</span><b>${esc(r.accessories||'—')}</b></div><div class="kpi"><span>نوع الصيانة</span><b>${esc(r.repairTypeName||'—')}</b></div><div class="kpi"><span>قيمة الصيانة</span><b>${money(r.amount||0)}</b></div><div class="kpi"><span>تكلفة قطع الغيار</span><b>${money(r.partsCost||0)}</b></div><div class="kpi"><span>الحالة الحالية</span><b>${esc(r.status)}</b></div><div class="kpi"><span>قرار العميل</span><b>${esc(r.decision||'لم يحدد')}</b></div><div class="kpi"><span>الملاحظات</span><b>${esc(r.note||'—')}</b></div></div><div class="form"><label>الحالة<select id="rst"><option ${r.status==='تحت الفحص'?'selected':''}>تحت الفحص</option><option ${r.status==='بانتظار العميل'?'selected':''}>بانتظار العميل</option><option ${r.status==='تم الإصلاح'?'selected':''}>تم الإصلاح</option><option ${r.status==='رفض'?'selected':''}>رفض</option><option ${r.status==='تم التسليم'?'selected':''}>تم التسليم</option></select></label><label>قرار العميل<select id="rdec"><option value="" ${!r.decision?'selected':''}>لم يحدد</option><option ${r.decision==='تم الإصلاح'?'selected':''}>تم الإصلاح</option><option ${r.decision==='رفض'?'selected':''}>رفض</option></select></label><label>قيمة الصيانة<input id="ra" type="number" value="${r.amount||''}"></label><label>حساب التحصيل<select id="repairAccount">${accountOptions(r.account||'drawer')}</select></label><label>موعد التسليم المتوقع<input id="red2" type="datetime-local" value="${r.expectedDelivery||''}"></label><label>الفني المسؤول<input id="rtech2" value="${esc(r.technician||'')}"></label><label>Serial Number<input id="rsn2" value="${esc(r.serial||'')}"></label><label>الملحقات<input id="racc2" value="${esc(r.accessories||'')}"></label><div class="full repair-parts"><b>قطع الغيار المستخدمة</b>${awaitRepairPartsHTML(r.parts||[])}</div><label class="full">ملاحظات<textarea id="rn2">${esc(r.note||'')}</textarea></label></div></div><div class="actions modal-actions">${r.phone?`<button class="btn whatsapp" onclick="whatsapp('${esc(r.phone)}','مرحباً ${esc(r.customer)}، معاك MAGHRABY STORE بخصوص جهاز ${esc(r.device)}. حالة الصيانة الحالية: ${esc(r.status)}.');">WhatsApp للعميل</button>`:''}<button class="btn" onclick="window.open('https://quickchart.io/qr?text=${qrText}&size=300','_blank','noopener')">QR للصيانة</button><button class="btn primary" onclick="updateRepair('${id}')">حفظ وتحديث</button></div>`)}
async function awaitRepairPartsHTML(selected=[]){let ps=await req('products');return ps.filter(p=>p.type!=='service'&&p.active!==false).map(p=>{let q=selected.find(x=>x.productId===p.id)?.qty||0;return `<label class="part-row"><span><input type="checkbox" class="repair-part-check" data-id="${p.id}" ${q?'checked':''}> ${esc(p.name)} <small>${money(p.cost)} • مخزون ${p.stock}</small></span><input class="repair-part-qty" data-id="${p.id}" type="number" min="0" value="${q}"></label>`}).join('')||'<div class="empty">لا توجد منتجات يمكن استخدامها كقطع غيار</div>'}
async function collectRepairParts(){let ps=await req('products');return [...document.querySelectorAll('.repair-part-check:checked')].map(c=>{let id=c.dataset.id,q=Number(document.querySelector(`.repair-part-qty[data-id="${id}"]`)?.value)||0,p=ps.find(x=>x.id===id);return {productId:id,qty:q,cost:Number(p?.cost||0),name:p?.name||''}}).filter(x=>x.qty>0)}

async function updateRepair(id){let r=(await req('repairs')).find(x=>x.id===id);if(!r)return;let oldStatus=r.status,newStatus=val('rst');r.decision=val('rdec');r.amount=Number(val('ra'))||0;r.account=val('repairAccount')||'drawer';r.expectedDelivery=val('red2')||r.expectedDelivery||'';r.technician=val('rtech2')||r.technician||'';r.serial=val('rsn2')||r.serial||'';r.accessories=val('racc2')||r.accessories||'';r.note=val('rn2');const parts=await collectRepairParts(),oldParts=r.parts||[],ps=await req('products');for(const np of parts){let op=oldParts.find(x=>x.productId===np.productId)?.qty||0,p=ps.find(x=>x.id===np.productId),delta=np.qty-op;if(p&&delta>p.stock)return toast(`المخزون لا يكفي لقطعة: ${p.name}`)}r.parts=parts;r.partsCost=parts.reduce((a,x)=>a+Number(x.cost||0)*Number(x.qty||0),0);
// Apply any new/removed repair parts before changing delivery status, so inventory stays correct even if payment is still pending.
const applyParts=async()=>{let tx=db.transaction(['repairs','products','stockMoves','audit'],'readwrite');for(const np of parts){let op=oldParts.find(x=>x.productId===np.productId)?.qty||0,delta=np.qty-op,p=ps.find(x=>x.id===np.productId);if(p&&delta){p.stock=Math.max(0,Number(p.stock||0)-delta);tx.objectStore('products').put(p);tx.objectStore('stockMoves').put({id:uid(),date:now(),productId:p.id,product:p.name,type:'repair',qty:-delta,ref:r.id,note:'قطع غيار صيانة'})}}tx.objectStore('repairs').put(r);tx.objectStore('audit').put({id:uid(),date:now(),action:'تحديث صيانة',data:r});await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error||new Error('repair transaction failed'));tx.onabort=()=>rej(tx.error||new Error('repair aborted'))})};
if(newStatus==='تم التسليم'&&oldStatus!=='تم التسليم'&&!r.paymentRecorded&&r.amount>0){r.status=oldStatus;r.pendingDelivery=true;await applyParts();await log('تحويل صيانة للكاشير',r);closeModal();state.page='sale';state.saleAccount=r.account||'drawer';state.saleCustomer='';state.discount=0;state.discountCode='';state.cartNote='صيانة '+(r.code||'')+' - '+(r.customer||'');state.cart=[{id:'repair:'+r.id,name:'صيانة '+(r.device||'جهاز')+' • '+(r.code||''),price:r.amount,cost:r.partsCost||0,qty:1,service:true,repairId:r.id}];await render();toast('تم تحويل الصيانة للكاشير — اختر الحساب وأكمل التحصيل');return}
r.status=newStatus;if(newStatus==='تم التسليم'&&oldStatus!=='تم التسليم'){r.deliveredAt=now();r.pendingDelivery=false}await applyParts();closeModal();toast('تم تحديث الصيانة');await render()}

async function inventory(v){
  let ps=await req('products');
  v.innerHTML=`<div class="section"><div><h2>المخزون — الكمية والقيمة والحد الأدنى</h2><p class="muted">تقدر تعدل المنتج أو تحذفه إذا كان مدخلًا بالخطأ، والمنتجات المستخدمة في فواتير سابقة يتم تعطيلها بدل حذف تاريخها.</p></div><div class="actions"><button class="btn" onclick="stockHistory()">حركة المخزون</button><button class="btn primary" onclick="productNew()">＋ منتج / خدمة</button></div></div>
  <div class="grid stats">${stat('قيمة المخزون',ps.filter(p=>p.type!=='service'&&p.active!==false).reduce((a,p)=>a+p.cost*p.stock,0),'بسعر التكلفة')}${stat('عدد الأصناف',ps.filter(p=>p.active!==false).length,'صنف','count')}${stat('تحت الحد الأدنى',ps.filter(p=>p.active!==false&&p.type!=='service'&&p.stock<=p.min&&p.min>0).length,'صنف','count')}</div>
  <div class="card table-wrap"><table class="table"><thead><tr><th>صورة</th><th>المنتج</th><th>القسم</th><th>التكلفة</th><th>البيع</th><th>الهامش</th><th>الموجود</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${ps.map(p=>`<tr class="${p.active===false?'inactive-row':''}"><td>${p.image?`<img src="${p.image}" style="width:45px;height:35px;object-fit:cover;border-radius:7px">`:p.emoji||'📦'}</td><td><b>${esc(p.name)}</b><br><small>${esc(p.note||'')}</small></td><td>${esc(p.cat||'')}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${money(p.price-p.cost)}</td><td><span class="badge ${p.stock<=p.min?'redbg':'green'}">${p.type==='service'?'خدمة':p.stock}</span></td><td>${p.active===false?'<span class="badge redbg">معطل</span>':'<span class="badge green">نشط</span>'}</td><td><div class="actions compact-actions"><button class="btn small" onclick="productEdit('${p.id}')">✎ تعديل</button>${p.active===false?`<button class="btn mint small" onclick="productToggle('${p.id}')">تفعيل</button>`:`<button class="btn orange small" onclick="productToggle('${p.id}')">تعطيل</button>`}<button class="btn red small" onclick="productDelete('${p.id}')">حذف</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">لا توجد منتجات. أضف أول منتج من الزر بالأعلى.</td></tr>'}</tbody></table></div>`
}
async function stockHistory(){let rows=await req('stockMoves');modal('حركة المخزون',`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الصنف</th><th>الحركة</th><th>الكمية</th><th>البيان</th></tr></thead><tbody>${rows.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${esc(x.product)}</td><td>${x.type}</td><td class="${x.qty<0?'negative':'positive'}">${x.qty>0?'+':''}${x.qty}</td><td>${esc(x.note||'')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد حركات مخزون</td></tr>'}</tbody></table></div>`)}
function productForm(p={}){let isEdit=!!p.id;return `<div class="form"><label>النوع<select id="pt"><option value="product" ${p.type!=='service'?'selected':''}>منتج له مخزون</option><option value="service" ${p.type==='service'?'selected':''}>خدمة بدون مخزون</option></select></label><label>اسم المنتج<input id="pn" value="${esc(p.name||'')}"></label><label>الباركود<input id="pbar" value="${esc(p.barcode||'')}"></label><label>القسم<input id="pc" value="${esc(p.cat||'')}" placeholder="أجهزة / دراعات / ألعاب / إكسسوارات / خدمات"></label><label>سعر البيع<input id="pp" type="number" value="${p.price??''}"></label><label>التكلفة علينا<input id="pk" type="number" value="${p.cost??''}"></label><label>الكمية<input id="pq" type="number" value="${p.type==='service'?'0':(p.stock??0)}"></label><label>الحد الأدنى<input id="pm" type="number" value="${p.type==='service'?'0':(p.min??1)}"></label><label>إيموجي<input id="pe" value="${esc(p.emoji||'📦')}"></label><label>صورة<input id="pi" type="file" accept="image/*"></label><label class="full">ملاحظة<textarea id="pno">${esc(p.note||'')}</textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveProduct('${p.id||''}')">${isEdit?'حفظ التعديلات':'حفظ المنتج'}</button>`}
function productNew(){modal('إضافة منتج / خدمة',productForm())}
async function productEdit(id){let p=(await req('products')).find(x=>x.id===id);if(p)modal('تعديل المنتج / الخدمة',productForm(p))}
async function productToggle(id){let p=(await req('products')).find(x=>x.id===id);if(!p)return;p.active=p.active===false;await put('products',p);await log(p.active?'تفعيل منتج':'تعطيل منتج',p);toast(p.active?'تم تفعيل المنتج':'تم تعطيل المنتج');render()}
async function productDelete(id){let p=(await req('products')).find(x=>x.id===id);if(!p)return;let [sales,purchases,returns]=await Promise.all([req('sales'),req('purchases'),req('returns')]);let used=sales.some(s=>s.items?.some(i=>i.id===id))||purchases.some(x=>x.productId===id)||returns.some(x=>x.itemId===id);if(used){return toast('المنتج مستخدم في معاملات سابقة؛ استخدم تعطيل بدل الحذف للحفاظ على التقارير')}if(!confirm(`حذف المنتج «${p.name}» نهائيًا؟`))return;await new Promise((res,rej)=>{let q=db.transaction('products','readwrite').objectStore('products').delete(id);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)});await log('حذف منتج',p);toast('تم حذف المنتج');render()}
function readFile(i){return new Promise(r=>{let f=$(i)?.files?.[0];if(!f)return r('');let x=new FileReader();x.onload=()=>r(x.result);x.readAsDataURL(f)})}
async function saveProduct(id=''){
  let old=id?(await req('products')).find(x=>x.id===id):null;
  let type=val('pt')||'product',name=val('pn');if(!name)return toast('اكتب اسم المنتج');
  let p={id:id||uid(),type,name,cat:val('pc')||'أخرى',price:Number(val('pp'))||0,cost:Number(val('pk'))||0,stock:type==='service'?0:Number(val('pq'))||0,min:type==='service'?0:Number(val('pm'))||0,emoji:val('pe')||'📦',image:await readFile('pi')||(old?.image||''),note:val('pno'),barcode:val('pbar'),active:old?.active!==false};
  if(old&&old.type!=='service'&&type!=='service'&&Number(val('pq'))<0)return toast('الكمية غير صحيحة');
  let oldStock=Number(old?.stock||0);await put('products',p);if(old&&p.type!=='service'&&oldStock!==Number(p.stock||0))await put('stockMoves',{id:uid(),date:now(),productId:p.id,product:p.name,type:'adjustment',qty:Number(p.stock||0)-oldStock,ref:p.id,note:'تعديل يدوي للمخزون'});await log(id?'تعديل منتج':'إضافة منتج',p);closeModal();toast(id?'تم حفظ تعديلات المنتج':'تم حفظ المنتج');render()
}
async function purchases(v){let ps=await req('products'),xs=await req('purchases');v.innerHTML=`<div class="section"><h2>المشتريات — البضاعة تدخل المخزون تلقائيًا</h2><button class="btn primary" onclick="purchaseNew()">＋ شراء بضاعة</button></div><div class="card"><div class="kpi"><span>قاعدة مهمة</span><b>ما سأبيعه للعميل = مشتريات / ما أستهلكه = مصروفات</b></div><div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الصنف</th><th>الكمية</th><th>التكلفة</th><th>الإجمالي</th><th>ملاحظة</th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${x.product}</td><td>${x.qty}</td><td>${money(x.unitCost)}</td><td>${money(x.total)}</td><td>${x.note||''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد مشتريات</td></tr>'}</tbody></table></div></div>`}
async function purchaseNew(){let ps=await req('products');modal('شراء بضاعة',`<div class="form"><label>الصنف<select id="bp">${ps.filter(p=>p.type!=='service').map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label>الكمية<input id="bq" type="number" value="1"></label><label>تكلفة الوحدة<input id="bc" type="number"></label><label>حساب الدفع<select id="purchaseAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظة<textarea id="bn" placeholder="مثال: شراء PS3 مستعمل من مورد..."></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="savePurchase()">حفظ</button>`)}
async function savePurchase(){let ps=await req('products'),p=ps.find(x=>x.id===val('bp'));if(!p)return toast('أضف منتجًا للمخزون أولًا');let q=Number(val('bq'))||1,c=Number(val('bc'))||p.cost,total=q*c;p.stock+=q;p.cost=c;await put('products',p);await put('stockMoves',{id:uid(),date:now(),productId:p.id,product:p.name,type:'purchase',qty:q,ref:p.id,note:'شراء بضاعة'});let x={id:uid(),date:now(),product:p.name,productId:p.id,qty:q,unitCost:c,total,note:val('bn')};await put('purchases',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:total,account:val('purchaseAccount')||'drawer',reason:'شراء بضاعة - '+p.name,ref:x.id,note:x.note});await log('شراء بضاعة',x);closeModal();toast('تمت الزيادة في المخزون وتسجيل الخرج');render()}
async function cash(v){let xs=await cashAll(),d=today(),balances=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));v.innerHTML=`<div class="grid three">${ACCOUNTS.map((a,i)=>`<div class="card"><div class="label">${a[1]}</div><div class="num">${money(balances[i].expected)}</div><div class="sub">بداية ${money(balances[i].opening)} · دخل ${money(balances[i].inc)} · خرج ${money(balances[i].out)}</div></div>`).join('')}</div><div class="section"><h2>دفتر الدخل والخرج</h2><div class="actions"><button class="btn mint" onclick="cashNew('in')">＋ دخل</button><button class="btn red" onclick="cashNew('out')">＋ خرج</button><button class="btn dark" onclick="transferNew()">⇄ تحويل بين الحسابات</button></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>الوقت</th><th>الحساب</th><th>النوع</th><th>البيان</th><th>دخل</th><th>خرج</th><th>ملاحظة</th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${accountName(x.account)}</td><td>${x.type==='in'?'داخل':'خارج'}</td><td>${x.reason}</td><td>${x.type==='in'?money(x.amount):'—'}</td><td>${x.type==='out'?money(x.amount):'—'}</td><td>${x.note||''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد حركات</td></tr>'}</tbody></table></div>`}
function transferNew(){modal('تحويل بين الحسابات',`<div class="transfer-note">التحويل لا يعتبر دخلًا أو خرجًا للمحل؛ هو نقل رصيد من حساب إلى حساب فقط.</div><div class="form"><label>من حساب<select id="tf">${accountOptions('drawer')}</select></label><label>إلى حساب<select id="tt">${accountOptions('wallet')}</select></label><label>المبلغ<input id="ta" type="number"></label><label class="full">ملاحظة<textarea id="tn" placeholder="مثال: تحويل جزء من الدرج إلى المحفظة"></textarea></label></div><button class="btn dark" style="margin-top:11px" onclick="saveTransfer()">تنفيذ التحويل</button>`)}
async function saveTransfer(){let from=val('tf'),to=val('tt'),amount=Number(val('ta'))||0;if(from===to)return toast('اختار حسابين مختلفين');if(!amount)return toast('اكتب المبلغ');let x={id:uid(),date:now(),from,to,amount,note:val('tn')};await put('transfers',x);await put('cash',{id:uid(),date:x.date,type:'out',amount,account:from,reason:'تحويل إلى '+accountName(to),ref:x.id,note:x.note,transfer:true});await put('cash',{id:uid(),date:x.date,type:'in',amount,account:to,reason:'تحويل من '+accountName(from),ref:x.id,note:x.note,transfer:true});await log('تحويل بين الحسابات',x);closeModal();toast('تم التحويل بدون التأثير على صافي دخل/خرج المحل');render()}
function cashNew(type){let opts=type==='in'?['دخل آخر','تحصيل','عربون','استرداد من مورد','أخرى']:['سلفة موظف','إيجار','كهرباء','مياه','معطر واستهلاك','نقل','أخرى'];modal(type==='in'?'دخل جديد':'خرج جديد',`<div class="form"><label>الحساب<select id="cashAccount">${accountOptions('drawer')}</select></label><label>المبلغ<input id="ca" type="number"></label><label>البيان<select id="cr">${opts.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="full">ملاحظة<textarea id="cn"></textarea></label></div><button class="btn ${type==='in'?'mint':'red'}" style="margin-top:11px" onclick="saveCash('${type}')">حفظ</button>`)}
async function saveCash(type){let a=Number(val('ca'))||0;if(!a)return toast('اكتب المبلغ');let x={id:uid(),date:now(),type,amount:a,account:val('cashAccount')||'drawer',reason:val('cr'),note:val('cn')};await put('cash',x);await log('حركة خزنة',x);closeModal();toast('تم حفظ الحركة');render()}
async function expenses(v){let xs=await req('expenses'),cashx=await cashAll(),total=xs.reduce((a,x)=>a+Number(x.amount||0),0),todayTotal=xs.filter(x=>x.date.slice(0,10)===today()).reduce((a,x)=>a+Number(x.amount||0),0);const accountFor=x=>{let c=cashx.find(c=>c.ref===x.id);return accountName(c?.account||'drawer')};v.innerHTML=`<div class="page-head"><div><span class="eyebrow">EXPENSES • MAGHRABY STORE</span><h2>مصروفات المحل</h2><p>سجل مصروفات التشغيل بشكل واضح، وكل مصروف يخصم من الحساب الذي اخترته.</p></div><div class="head-actions"><button class="btn red" onclick="expenseNew()">＋ إضافة مصروف</button></div></div><div class="grid three expense-summary"><div class="card expense-kpi"><small>مصروفات اليوم</small><strong>${money(todayTotal)}</strong></div><div class="card expense-kpi"><small>إجمالي المصروفات المسجلة</small><strong>${money(total)}</strong></div><div class="card expense-kpi"><small>عدد العمليات</small><strong>${xs.length} مصروف</strong></div></div><div class="section"><h2>أنواع المصروفات</h2></div><div class="expense-types"><div><b>إيجار</b><small>تشغيل</small></div><div><b>كهرباء / مياه</b><small>خدمات</small></div><div><b>إنترنت</b><small>خدمات</small></div><div><b>نقل</b><small>تشغيل</small></div><div><b>تنظيف واستهلاك</b><small>تشغيل</small></div><div><b>أخرى</b><small>مصروف متنوع</small></div></div><div class="section"><h2>سجل المصروفات</h2></div><div class="card table-wrap expense-table-card"><table class="table"><thead><tr><th>التاريخ والوقت</th><th>النوع</th><th>حساب الدفع</th><th>المبلغ</th><th>الملاحظة</th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td><span class="badge redbg">${esc(x.type)}</span></td><td>${accountFor(x)}</td><td><b class="negative">${money(x.amount)}</b></td><td>${esc(x.note||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد مصروفات حتى الآن</td></tr>'}</tbody></table></div>`}
function expenseNew(){modal('مصروف تشغيل',`<div class="form"><label>النوع<select id="et"><option>إيجار</option><option>كهرباء</option><option>مياه</option><option>إنترنت</option><option>معطر / تنظيف</option><option>نقل</option><option>أخرى</option></select></label><label>المبلغ<input id="ea" type="number"></label><label>حساب الدفع<select id="expenseAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظة<textarea id="en"></textarea></label></div><button class="btn red" style="margin-top:11px" onclick="saveExpense()">حفظ</button>`)}
async function saveExpense(){let a=Number(val('ea'))||0,x={id:uid(),date:now(),type:val('et'),amount:a,note:val('en')};await put('expenses',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:a,account:val('expenseAccount')||'drawer',reason:x.type,ref:x.id,note:x.note});await log('مصروف',x);closeModal();toast('تم تسجيل المصروف');render()}
async function staff(v){let xs=await req('staff'),cashx=await req('cash');v.innerHTML=`<div class="section"><h2>الفنيون والموظفون — السلف والمستحقات</h2><button class="btn primary" onclick="staffNew()">＋ موظف / فني</button></div><div class="card"><p style="color:var(--muted)">هنا نسجل الأشخاص العاملين وسلفهم. السلفة تظهر تلقائيًا كخرج من الخزنة، بدل ما تختلط بالمشتريات أو مصروفات المحل.</p><div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>الدور</th><th>السلف</th><th>ملاحظات</th><th></th></tr></thead><tbody>${xs.map(x=>{let adv=cashx.filter(c=>c.type==='out'&&c.reason==='سلفة موظف'&&c.staffId===x.id).reduce((a,c)=>a+c.amount,0);return `<tr><td><b>${x.name}</b></td><td>${x.role}</td><td>${money(adv)}</td><td>${x.note||''}</td><td><button class="btn orange" onclick="advance('${x.id}')">سلفة</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">أضف الفنيين والموظفين عند الحاجة</td></tr>'}</tbody></table></div></div>`}
function staffNew(){modal('إضافة فني / موظف',`<div class="form"><label>الاسم<input id="sn"></label><label>الدور<input id="sr" placeholder="فني / موظف / إداري"></label><label class="full">ملاحظة<textarea id="sno"></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveStaff()">حفظ</button>`)}
async function saveStaff(){let x={id:uid(),name:val('sn'),role:val('sr'),note:val('sno')};await put('staff',x);closeModal();toast('تم إضافة الشخص');render()}
async function advance(id){let s=(await req('staff')).find(x=>x.id===id);modal('سلفة — '+s.name,`<div class="form"><label>المبلغ<input id="ava" type="number"></label><label>حساب الدفع<select id="advanceAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظة<textarea id="avn"></textarea></label></div><button class="btn red" style="margin-top:11px" onclick="saveAdvance('${id}')">تسجيل السلفة</button>`)}
async function saveAdvance(id){let a=Number(val('ava'))||0;if(!a)return toast('اكتب المبلغ');await put('cash',{id:uid(),date:now(),type:'out',amount:a,account:val('advanceAccount')||'drawer',reason:'سلفة موظف',staffId:id,note:val('avn')});closeModal();toast('تم تسجيل السلفة كخرج من الخزنة');render()}
async function accounts(v){let xs=await req('accounts');v.innerHTML=`<div class="section"><div><h2>حسابات العملاء</h2><p class="muted">بيانات الحسابات المحفوظة للعميل، منفصلة عن الدرج والمحفظة وInstaPay.</p></div><button class="btn primary" onclick="accountNew()">＋ حساب عميل</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>البريد</th><th>اسم المستخدم</th><th>ملاحظات</th><th></th></tr></thead><tbody>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email||'')}</td><td>${esc(x.username||'')}</td><td>${esc(x.note||'')}</td><td><button class="btn small red" onclick="accountDelete('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد حسابات</td></tr>'}</tbody></table></div>`}
function accountNew(){modal('حساب عميل',`<div class="form"><label>الاسم<input id="an"></label><label>البريد الإلكتروني<input id="ae" type="email"></label><label>اسم المستخدم<input id="au"></label><label>كلمة المرور<input id="ap" type="password"></label><label class="full">ملاحظة<textarea id="ano"></textarea></label></div><button class="btn primary" onclick="saveAccount()">حفظ</button>`)}
async function saveAccount(){let x={id:uid(),date:now(),name:val('an'),email:val('ae'),username:val('au'),password:val('ap'),note:val('ano')};if(!x.name)return toast('اكتب الاسم');await put('accounts',x);closeModal();toast('تم حفظ الحساب');render()}
async function accountDelete(id){let x=(await req('accounts')).find(x=>x.id===id);if(!x||!confirm('حذف الحساب؟'))return;await new Promise((res,rej)=>{let q=db.transaction('accounts','readwrite').objectStore('accounts').delete(id);q.onsuccess=res;q.onerror=()=>rej(q.error)});toast('تم حذف الحساب');render()}
async function customers(v){let xs=await req('customers'),q=(state.q||'').toLowerCase();xs=xs.filter(x=>x.name.toLowerCase().includes(q)||String(x.phone||'').includes(q));v.innerHTML=`<div class="section"><div><h2>العملاء</h2><p class="muted">ملف العميل، الهاتف، الملاحظات، والمبيعات والصيانة المرتبطة به.</p></div><button class="btn primary" onclick="customerNew()">＋ عميل</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>الهاتف</th><th>ملاحظات</th><th>تاريخ الإضافة</th><th></th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.phone||'')}</td><td>${esc(x.note||'')}</td><td>${new Date(x.date).toLocaleDateString('ar-EG')}</td><td><button class="btn small" onclick="customerEdit('${x.id}')">تعديل</button><button class="btn small red" onclick="customerDelete('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا يوجد عملاء</td></tr>'}</tbody></table></div></div>`}

function customerNew(){modal('عميل جديد',`<div class="form"><label>الاسم<input id="cname"></label><label>الهاتف<input id="cphone"></label><label class="full">ملاحظة<textarea id="cnote" placeholder="دائم / يفضل خصم / ملاحظة خدمة..."></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveCustomer()">حفظ</button>`)}
async function saveCustomer(){let x={id:uid(),date:now(),name:val('cname'),phone:val('cphone'),note:val('cnote')};if(!x.name)return toast('اكتب اسم العميل');await put('customers',x);closeModal();toast('تم حفظ العميل');render()}
async function customerEdit(id){let x=(await req('customers')).find(x=>x.id===id);if(!x)return;modal('تعديل العميل',`<div class="form"><label>الاسم<input id="cname" value="${esc(x.name)}"></label><label>الهاتف<input id="cphone" value="${esc(x.phone||'')}"></label><label class="full">ملاحظة<textarea id="cnote">${esc(x.note||'')}</textarea></label></div><button class="btn primary" onclick="saveCustomerEdit('${id}')">حفظ التعديلات</button>`)}
async function saveCustomerEdit(id){let x=(await req('customers')).find(x=>x.id===id);if(!x)return;x.name=val('cname');x.phone=val('cphone');x.note=val('cnote');if(!x.name)return toast('اكتب اسم العميل');await put('customers',x);closeModal();toast('تم تعديل العميل');render()}
async function customerDelete(id){let x=(await req('customers')).find(x=>x.id===id);if(!x||!confirm('حذف العميل؟'))return;let [sales,repairs]=await Promise.all([req('sales'),req('repairs')]);if(sales.some(s=>s.customerId===id)||repairs.some(r=>r.customerId===id))return toast('العميل مرتبط بفواتير؛ عدّل بياناته بدل حذفه');await new Promise((res,rej)=>{let q=db.transaction('customers','readwrite').objectStore('customers').delete(id);q.onsuccess=res;q.onerror=()=>rej(q.error)});toast('تم حذف العميل');render()}

async function discounts(v){let codes=await req('discountCodes');v.innerHTML=`<div class="page-head"><div><span class="eyebrow">DISCOUNT CODES</span><h2>أكواد الخصم</h2><p>أنشئ أكواد خصم محددة بالقيمة أو النسبة مع صلاحية وحد أقصى للاستخدام.</p></div><button class="btn orange" onclick="discountCodeNew()">＋ كود خصم</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>الكود</th><th>النوع</th><th>القيمة</th><th>من</th><th>إلى</th><th>الاستخدام</th><th></th></tr></thead><tbody>${codes.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${x.kind==='percent'?'نسبة':'مبلغ'}</td><td>${x.kind==='percent'?x.value+'%':money(x.value)}</td><td>${x.start||'—'}</td><td>${x.end||'—'}</td><td>${x.used||0}${x.maxUses?' / '+x.maxUses:''}</td><td><button class="btn small red" onclick="discountCodeDelete('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد أكواد خصم</td></tr>'}</tbody></table></div>`}
async function returns(v){let rs=await req('returns');let sales=await req('sales');v.innerHTML=`<div class="page-head"><div><span class="eyebrow">RETURNS</span><h2>المرتجعات</h2><p>إرجاع الصنف للمخزون ورد المبلغ من الحساب الصحيح بدون كسر حركة اليوم.</p></div><button class="btn primary" onclick="returnNew()">＋ تسجيل مرتجع</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الفاتورة</th><th>الصنف</th><th>الكمية</th><th>المبلغ</th><th>الحساب</th><th>السبب</th></tr></thead><tbody>${rs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${x.invoiceRef||'—'}</td><td>${esc(x.itemName)}</td><td>${x.qty}</td><td>${money(x.total)}</td><td>${accountName(x.account)}</td><td>${esc(x.reason||'')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد مرتجعات</td></tr>'}</tbody></table></div>`}
async function returnNew(){let sales=await req('sales');if(!sales.length)return toast('لا توجد فواتير بيع يمكن إرجاعها');modal('تسجيل مرتجع',`<div class="form"><label class="full">الفاتورة<select id="rrsale">${sales.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<option value="${x.id}">${new Date(x.date).toLocaleString('ar-EG')} • ${esc(x.customerName||'عميل نقدي')} • ${money(x.total)}</option>`).join('')}</select></label><label>الصنف<select id="rritem"></select></label><label>الكمية<input id="rrqty" type="number" value="1" min="1"></label><label>حساب رد المبلغ<select id="rraccount">${accountOptions('drawer')}</select></label><label class="full">سبب المرتجع<textarea id="rrreason" placeholder="عيب / تغيير رأي / غير مناسب... "></textarea></label></div><button class="btn red" style="margin-top:11px" onclick="saveReturn()">تسجيل المرتجع ورد المبلغ</button>`);let sel=$('rrsale');let fill=async()=>{let s=(await req('sales')).find(x=>x.id===sel.value);$('rritem').innerHTML=(s?.items||[]).map((i,n)=>`<option value="${n}">${esc(i.name)} • ${i.qty} × ${money(i.price)}</option>`).join('')};sel.onchange=fill;await fill()}
async function saveReturn(){let sales=await req('sales'),s=sales.find(x=>x.id===val('rrsale'));if(!s)return;let idx=Number(val('rritem')),item=s.items[idx],qty=Number(val('rrqty'))||0;if(!item||qty<1||qty>item.qty)return toast('كمية المرتجع غير صحيحة');let total=qty*Number(item.price||0),x={id:uid(),date:now(),saleId:s.id,invoiceRef:s.id.slice(0,8),itemName:item.name,itemId:item.id,qty,total,account:val('rraccount')||'drawer',reason:val('rrreason')};await put('returns',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:total,account:x.account,reason:'مرتجع بيع - '+item.name,ref:x.id});await put('invoices',{id:uid(),date:x.date,type:'مرتجع',total,ref:x.id,account:x.account,note:x.reason});let ps=await req('products'),p=ps.find(p=>p.id===item.id);if(p&&p.type!=='service'){p.stock+=qty;await put('products',p);await put('stockMoves',{id:uid(),date:x.date,productId:p.id,product:p.name,type:'return',qty:qty,ref:x.id,note:'مرتجع بيع'})}await log('مرتجع بيع',x);closeModal();toast('تم تسجيل المرتجع وإعادة الكمية للمخزون');render()}
async function needs(v){let ps=await req('products'),low=ps.filter(p=>p.type!=='service'&&p.stock<=p.min&&p.min>0);v.innerHTML=`<div class="section"><h2>قائمة الاحتياجات — النظام يرشحها لك</h2><button class="btn primary" onclick="state.page='purchases';render()">فتح المشتريات</button></div><div class="card">${low.map(p=>`<div class="kpi"><span>📦 <b>${p.name}</b><small> — الموجود ${p.stock} / الحد ${p.min}</small></span><button class="btn orange" onclick="toast('تم تمييز ${p.name} كاحتياج')">مطلوب</button></div>`).join('')||'<div class="empty">مفيش أصناف تحت الحد الأدنى 🎉</div>'}</div>`}
async function reports(v){let [s,r,e,c,days]=await Promise.all([req('sales'),req('repairs'),req('expenses'),cashAll(),req('days')]),d=today(),dt=new Date(),weekStart=new Date(dt);weekStart.setDate(dt.getDate()-6);weekStart.setHours(0,0,0,0),monthStart=new Date(dt.getFullYear(),dt.getMonth(),1),yearStart=new Date(dt.getFullYear(),0,1);const period=(start)=>({start,rows:c.filter(x=>new Date(x.date)>=start&&new Date(x.date)<=dt)}),sumRows=rows=>({inc:rows.filter(x=>x.type==='in'&&!x.transfer).reduce((a,x)=>a+x.amount,0),out:rows.filter(x=>x.type==='out'&&!x.transfer).reduce((a,x)=>a+x.amount,0)}),W=period(weekStart),M=period(monthStart),Y=period(yearStart),sd=s.filter(x=>x.date.slice(0,10)===d),rd=r.filter(x=>x.date.slice(0,10)===d&&x.status==='تم التسليم'),ed=e.filter(x=>x.date.slice(0,10)===d),sales=sd.reduce((a,x)=>a+(x.items.some(i=>i.repairId)?0:x.total),0),cogs=sd.reduce((a,x)=>a+x.items.reduce((z,i)=>z+i.cost*i.qty,0),0),repIncome=rd.reduce((a,x)=>a+(x.amount||0),0),repPartsCost=rd.reduce((a,x)=>a+(x.partsCost||0),0),op=ed.reduce((a,x)=>a+x.amount,0),profit=sales+repIncome-cogs-repPartsCost-op,closed=days.find(x=>x.date===d);let B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));v.innerHTML=`<div class="grid stats">${stat('مبيعات اليوم',sales,'بعد الخصم')}${stat('دخل الصيانة',repIncome,'المسلّم اليوم')}${stat('مصروفات التشغيل',op,'بدون المشتريات')}${stat('الربح التقريبي',profit,'بعد التكلفة والمصروفات')}${stat('المتوقع في الدرج',B[0].expected,'رصيد بداية + حركة اليوم')}${stat('إجمالي الأرصدة الرقمية',B[1].expected+B[2].expected,'محفظة + InstaPay')}</div><div class="section"><h2>🔒 إقفال اليوم</h2><div class="actions"><button class="btn primary" onclick="closeDay()">عدّ الدرج والمحافظ وإقفال اليوم</button><button class="btn" onclick="printReportsPDF()">تصدير / حفظ PDF</button></div></div><div class="card close-box"><div class="grid three">${ACCOUNTS.map((a,i)=>`<div><small>${a[1]}</small><div class="expected">${money(B[i].expected)}</div><div class="sub">بداية ${money(B[i].opening)} · دخل ${money(B[i].inc)} · خرج ${money(B[i].out)}</div></div>`).join('')}</div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><b>${closed?'اليوم مقفول بالفعل ويمكن مراجعة أرقامه.':'الإقفال يحفظ الرصيد الفعلي لكل حساب ليصبح رصيد بداية اليوم التالي تلقائيًا.'}</b></div><div class="section"><h2>📊 الدخل والخرج — أسبوعي / شهري / سنوي</h2></div><div class="grid three">${[['الأسبوع الحالي',W],['الشهر الحالي',M],['السنة الحالية',Y]].map(([n,x])=>{let q=sumRows(x.rows);return `<div class="card"><h3>${n}</h3><div class="kpi"><span>إجمالي الداخل</span><b class="positive">${money(q.inc)}</b></div><div class="kpi"><span>إجمالي الخارج</span><b class="negative">${money(q.out)}</b></div><div class="kpi"><span>صافي الحركة</span><b>${money(q.inc-q.out)}</b></div></div>`}).join('')}</div><div class="section"><h2>تفصيل حسب الحساب</h2></div><div class="card table-wrap"><table class="table"><thead><tr><th>الفترة</th>${ACCOUNTS.map(a=>`<th>${a[1]} دخل</th><th>${a[1]} خرج</th>`).join('')}</tr></thead><tbody>${[['أسبوعي',W.rows],['شهري',M.rows],['سنوي',Y.rows]].map(([n,rows])=>`<tr><td>${n}</td>${ACCOUNTS.map(a=>{let z=sumRows(rows.filter(x=>x.account===a[0]));return `<td>${money(z.inc)}</td><td>${money(z.out)}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="section"><h2>تحليل اليوم</h2></div><div class="grid two"><div class="card"><div class="kpi"><span>عدد عمليات البيع</span><b>${sd.length}</b></div><div class="kpi"><span>خصومات اليوم</span><b>${money(sd.reduce((a,x)=>a+x.discount,0))}</b></div><div class="kpi"><span>أجهزة تم تسليمها</span><b>${rd.length}</b></div></div><div class="card"><div class="kpi"><span>قيمة المبيعات + الصيانة</span><b>${money(sales+repIncome)}</b></div><div class="kpi"><span>تكلفة البضاعة</span><b>${money(cogs)}</b></div><div class="kpi"><span>تكلفة قطع غيار الصيانة</span><b>${money(repPartsCost)}</b></div><div class="kpi"><span>هامش تقريبي</span><b class="${profit>=0?'positive':'negative'}">${money(profit)}</b></div><div class="section"><h2>🗂️ مراجعة التاريخ</h2><span class="muted">السجل لا يُحذف تلقائيًا حسب السنة؛ يمكنك مراجعة سنوات متعددة طالما بيانات المتصفح موجودة.</span></div><div class="card"><div class="form compact"><label>السنة<select id="historyYear"></select></label><label>الشهر<select id="historyMonth"><option value="all">كل الشهور</option><option value="01">يناير</option><option value="02">فبراير</option><option value="03">مارس</option><option value="04">أبريل</option><option value="05">مايو</option><option value="06">يونيو</option><option value="07">يوليو</option><option value="08">أغسطس</option><option value="09">سبتمبر</option><option value="10">أكتوبر</option><option value="11">نوفمبر</option><option value="12">ديسمبر</option></select></label></div><div id="historyResult" style="margin-top:14px"></div></div><div class="section"><h2>💾 حفظ طويل المدى</h2></div><div class="card"><p class="muted">البرنامج لا يضع حدًا مثل سنة أو سنتين؛ المعاملات تظل محفوظة محليًا حتى تحذف بيانات الموقع/المتصفح أو تستورد نسخة أخرى. اعمل Backup دوريًا، ويفضل نسخة شهرية وسنوية خارج الجهاز.</p></div></div>`;initHistory()}
async function initHistory(){let years=new Set([String(new Date().getFullYear())]);for(const store of ['cash','sales','repairs','expenses','purchases'])for(const x of await req(store)){if(x.date)years.add(String(new Date(x.date).getFullYear()))}let ys=[...years].sort((a,b)=>b.localeCompare(a));$('historyYear').innerHTML=ys.map(y=>`<option value="${y}">${y}</option>`).join('');$('historyYear').value=String(new Date().getFullYear());$('historyMonth').value='all';$('historyYear').onchange=historyRefresh;$('historyMonth').onchange=historyRefresh;historyRefresh()}
async function historyRefresh(){let y=$('historyYear').value,m=$('historyMonth').value,rows=(await cashAll()).filter(x=>{let d=new Date(x.date);return String(d.getFullYear())===y&&(m==='all'||String(d.getMonth()+1).padStart(2,'0')===m)}),inc=rows.filter(x=>x.type==='in'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0),out=rows.filter(x=>x.type==='out'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0);let by=Object.fromEntries(ACCOUNTS.map(a=>[a[0],{in:0,out:0}]));rows.forEach(x=>{if(by[x.account]&&!x.transfer)by[x.account][x.type]+=Number(x.amount||0)});$('historyResult').innerHTML=`<div class="grid four"><div class="kpi"><span>إجمالي الداخل</span><b class="positive">${money(inc)}</b></div><div class="kpi"><span>إجمالي الخارج</span><b class="negative">${money(out)}</b></div><div class="kpi"><span>صافي الحركة</span><b>${money(inc-out)}</b></div><div class="kpi"><span>عدد الحركات</span><b>${rows.length}</b></div></div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>الحساب</th><th>الدخل</th><th>الخرج</th><th>الصافي</th></tr></thead><tbody>${ACCOUNTS.map(a=>`<tr><td>${a[1]}</td><td>${money(by[a[0]].in)}</td><td>${money(by[a[0]].out)}</td><td>${money(by[a[0]].in-by[a[0]].out)}</td></tr>`).join('')}</tbody></table></div>`}

async function closeDay(){let d=today(),B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0]))),old=await dayRecord(d);modal('إقفال اليوم — عدّ كل الحسابات',`<div class="grid three">${ACCOUNTS.map((a,i)=>`<div class="card"><small>${a[1]} — المتوقع</small><div class="expected">${money(B[i].expected)}</div><small>بداية ${money(B[i].opening)} + دخل ${money(B[i].inc)} − خرج ${money(B[i].out)}</small></div>`).join('')}</div><div class="form" style="margin-top:12px">${ACCOUNTS.map(a=>`<label>الرصيد الفعلي — ${a[1]}<input id="count_${a[0]}" type="number" value="${old?.[a[0]+'Counted']??(a[0]==='drawer'?(old?.counted??''):'')}"></label>`).join('')}<label class="full">ملاحظة الإقفال<textarea id="dn">${old?.note||''}</textarea></label></div><div id="difference" style="margin-top:10px"></div><button class="btn primary" style="margin-top:10px" onclick="saveDay('${d}')">حفظ الإقفال</button>`);for(const a of ACCOUNTS){$('count_'+a[0]).oninput=()=>{let html=ACCOUNTS.map(x=>{let expected=B.find((_,i)=>ACCOUNTS[i][0]===x[0]).expected,count=Number($('count_'+x[0]).value)||0;return `<div class=\"kpi\"><span>${x[1]}</span><b class=\"${count-expected===0?'positive':'negative'}\">${count-expected===0?'مطابق':'فرق '+money(count-expected)}</b></div>`}).join('');$('difference').innerHTML=html}}}
async function saveDay(d){let B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0]))),x={id:d,date:d,note:val('dn'),closedAt:now()};ACCOUNTS.forEach((a,i)=>{let counted=Number(val('count_'+a[0]))||0;x[a[0]+'Opening']=B[i].opening;x[a[0]+'Expected']=B[i].expected;x[a[0]+'Counted']=counted;x[a[0]+'Difference']=counted-B[i].expected});x.expected=x.drawerExpected;x.counted=x.drawerCounted;x.difference=x.drawerDifference;await put('days',x);closeModal();toast('تم إقفال اليوم وحفظ أرصدة الدرج والمحفظة وInstaPay');render()}
async function invoices(v){let xs=await req('invoices'),sales=await req('sales');const known=new Set(xs.map(x=>x.ref));for(const s of sales){if(!known.has(s.id)){let inv={id:'INV-'+s.id,date:s.date,type:'بيع',total:s.total,ref:s.id,note:s.note||'',account:s.account,customerId:s.customerId||'',customerName:s.customerName||'',discount:s.discount||0,discountCode:s.discountCode||''};await put('invoices',inv);xs.push(inv)}}xs.sort((a,b)=>b.date.localeCompare(a.date));v.innerHTML=`<div class="page-head"><div><span class="eyebrow">INVOICES • MAGHRABY STORE</span><h2>الفواتير</h2><p>كل فاتورة محفوظة من الكاشير تظهر هنا ويمكن إعادة طباعتها في أي وقت.</p></div><div class="head-actions"><button class="btn primary" data-page="sale">＋ فاتورة جديدة</button></div></div><div class="grid three invoice-summary"><div class="card expense-kpi"><small>عدد الفواتير</small><strong>${xs.length} فاتورة</strong></div><div class="card expense-kpi"><small>إجمالي الفواتير</small><strong>${money(xs.reduce((a,x)=>a+Number(x.total||0),0))}</strong></div><div class="card expense-kpi"><small>آخر فاتورة</small><strong>${xs[0]?new Date(xs[0].date).toLocaleDateString('ar-EG'):'—'}</strong></div></div><div class="card table-wrap invoice-table-card"><table class="table"><thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>العميل</th><th>الحساب</th><th>الإجمالي</th><th></th></tr></thead><tbody>${xs.map((x,i)=>`<tr><td><b>INV-${String(xs.length-i).padStart(5,'0')}</b></td><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${esc(x.customerName||'عميل نقدي')}</td><td>${accountName(x.account||'drawer')}</td><td><b>${money(x.total)}</b></td><td>${x.type==='بيع'?`<button class="btn small" onclick="reprint('${x.ref}')">إعادة طباعة</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد فواتير حتى الآن. أنشئ أول فاتورة من شاشة الكاشير.</td></tr>'}</tbody></table></div>`}
async function reprint(ref){let x=(await req('sales')).find(s=>s.id===ref);if(x)printInvoice(x)}
function printInvoice(x){let items=x.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.price*i.qty)}</td></tr>`).join('');let w=window.open('','_blank');if(!w)return toast('المتصفح منع نافذة الطباعة');let logoUrl=new URL('public/logo.png',location.href).href;w.document.write(`<html dir="rtl"><head><title>فاتورة MAGHRABY STORE</title><style>body{font-family:Arial,sans-serif;padding:25px;color:#102a43}.brand{display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:8px}.brand img{width:58px;height:58px;object-fit:contain;border-radius:12px}.brand h1{margin:0;font-size:27px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:right}.total{font-size:22px;font-weight:bold;margin-top:20px}.note{margin-top:15px;background:#f4f7f8;padding:10px;border-radius:8px}</style></head><body><div class="brand"><img src="${logoUrl}" alt="MAGHRABY STORE"><h1>MAGHRABY STORE</h1></div><p>${new Date(x.date).toLocaleString('ar-EG')}</p><table><tr><th>الصنف</th><th>العدد</th><th>السعر</th><th>الإجمالي</th></tr>${items}</table><p>قبل الخصم: ${money(x.subtotal)}</p><p>الخصم: ${money(x.discount)}</p><div class="total">الإجمالي: ${money(x.total)}</div><div class="note">${esc(x.note||'')}</div><script>window.print()<\/script></body></html>`);w.document.close()}
async function printReportsPDF(){let d=today(),s=await req('sales'),r=await req('repairs'),e=await req('expenses'),c=await cashAll(),inc=c.filter(x=>x.date.slice(0,10)===d&&x.type==='in'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0),out=c.filter(x=>x.date.slice(0,10)===d&&x.type==='out'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0),sales=s.filter(x=>x.date.slice(0,10)===d).reduce((a,x)=>a+x.total,0),rep=r.filter(x=>x.date.slice(0,10)===d&&x.status==='تم التسليم').reduce((a,x)=>a+Number(x.amount||0),0),exp=e.filter(x=>x.date.slice(0,10)===d).reduce((a,x)=>a+Number(x.amount||0),0);let w=window.open('','_blank');if(!w)return toast('المتصفح منع نافذة التقرير');w.document.write(`<html dir=rtl><head><title>تقرير MAGHRABY STORE</title><style>body{font-family:Arial;padding:28px;color:#102a43}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:right}.box{padding:14px;border:1px solid #ddd;border-radius:10px;margin-top:12px}</style></head><body><div style="display:flex;align-items:center;gap:10px"><img src="${new URL('public/logo.png',location.href).href}" style="width:55px;height:55px;object-fit:contain;border-radius:10px"><h1>MAGHRABY STORE</h1></div><p>تقرير يوم ${d}</p><div class=box>المبيعات: ${money(sales)}<br>دخل الصيانة: ${money(rep)}<br>المصروفات: ${money(exp)}<br>إجمالي الداخل: ${money(inc)}<br>إجمالي الخارج: ${money(out)}<br>صافي الحركة: ${money(inc-out)}</div><table><tr><th>البيان</th><th>القيمة</th></tr><tr><td>عدد الفواتير</td><td>${s.filter(x=>x.date.slice(0,10)===d).length}</td></tr><tr><td>عدد الصيانات المسلمة</td><td>${r.filter(x=>x.date.slice(0,10)===d&&x.status==='تم التسليم').length}</td></tr></table><script>window.print()<\/script></body></html>`);w.document.close()}
async function settings(v){let fs=(await req('settings')).find(x=>x.id==='finance')||{},types=await req('repairTypes'),codes=await req('discountCodes');v.innerHTML=`<div class="page-head"><div><span class="eyebrow">CONTROL CENTER</span><h2>الإعدادات والنظام</h2><p>إعدادات التشغيل الأساسية في مكان واحد.</p></div></div><div class="grid two"><div class="card settings-card"><h3>💰 أرصدة البداية</h3><div class="form compact"><label>الدرج<input id="open_drawer" type="number" value="${fs.drawerOpening||''}"></label><label>المحفظة<input id="open_wallet" type="number" value="${fs.walletOpening||''}"></label><label>InstaPay<input id="open_instapay" type="number" value="${fs.instapayOpening||''}"></label></div><button class="btn primary" onclick="saveOpenings()">حفظ أرصدة البداية</button></div><div class="card settings-card"><h3>💾 النسخ الاحتياطي</h3><p class="muted">يوجد حفظ احتياطي تلقائي يومي داخل قاعدة البيانات لآخر 30 يومًا، بالإضافة إلى Backup خارجي.</p><div class="actions"><button class="btn primary" onclick="backup()">تصدير Backup</button><label class="btn">استيراد Backup<input type="file" hidden accept=".json" onchange="restore(this.files[0])"></label></div></div></div><div class="section"><h2>🔧 أنواع الصيانة والأسعار</h2><button class="btn mint" onclick="repairTypeNew()">＋ نوع صيانة</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>النوع</th><th>السعر</th><th></th></tr></thead><tbody>${types.map(x=>`<tr><td>${esc(x.name)}</td><td>${money(x.price)}</td><td><button class="btn small" onclick="repairTypeEdit('${x.id}')">تعديل</button><button class="btn small red" onclick="repairTypeDelete('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="3" class="empty">لا توجد أنواع صيانة</td></tr>'}</tbody></table></div><div class="section"><h2>🏷️ أكواد الخصم</h2><button class="btn orange" onclick="discountCodeNew()">＋ كود خصم</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>الكود</th><th>الخصم</th><th>الصلاحية</th><th>الاستخدام</th><th></th></tr></thead><tbody>${codes.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${x.kind==='percent'?x.value+'%':money(x.value)}</td><td>${x.start||'—'} → ${x.end||'—'}</td><td>${x.used||0}${x.maxUses?' / '+x.maxUses:''}</td><td><button class="btn small red" onclick="discountCodeDelete('${x.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد أكواد خصم</td></tr>'}</tbody></table></div><div class="card settings-card"><h3>🎨 الهوية</h3><img src="public/logo.png" class="settings-logo"><p class="muted">اللوجو الرسمي PNG والواجهة بألوان الهوية.</p></div>`}
function repairTypeNew(){modal('نوع صيانة',`<div class="form"><label>الاسم<input id="rtn"></label><label>السعر<input id="rtp" type="number"></label></div><button class="btn primary" onclick="saveRepairType()">حفظ</button>`)}
async function repairTypeEdit(id){let x=(await req('repairTypes')).find(x=>x.id===id);if(!x)return;modal('تعديل نوع صيانة',`<div class="form"><label>الاسم<input id="rtn" value="${esc(x.name)}"></label><label>السعر<input id="rtp" type="number" value="${x.price}"></label></div><button class="btn primary" onclick="saveRepairType('${id}')">حفظ</button>`)}
async function saveRepairType(id=''){let x={id:id||uid(),name:val('rtn'),price:Number(val('rtp'))||0,active:true};if(!x.name)return toast('اكتب اسم الصيانة');await put('repairTypes',x);closeModal();toast('تم حفظ نوع الصيانة');render()}
async function repairTypeDelete(id){let x=(await req('repairTypes')).find(x=>x.id===id);if(!x||!confirm('حذف نوع الصيانة؟'))return;await new Promise((res,rej)=>{let q=db.transaction('repairTypes','readwrite').objectStore('repairTypes').delete(id);q.onsuccess=res;q.onerror=()=>rej(q.error)});render()}
function discountCodeNew(){modal('كود خصم',`<div class="form"><label>الكود<input id="dcn" placeholder="MAGHRABY10"></label><label>النوع<select id="dck"><option value="percent">نسبة %</option><option value="amount">مبلغ</option></select></label><label>القيمة<input id="dcv" type="number"></label><label>أقصى استخدامات<input id="dcm" type="number"></label><label>من<input id="dcs" type="date"></label><label>إلى<input id="dce" type="date"></label></div><button class="btn primary" onclick="saveDiscountCode()">حفظ</button>`)}
async function saveDiscountCode(){let x={id:uid(),code:val('dcn').toUpperCase(),kind:val('dck'),value:Number(val('dcv'))||0,maxUses:Number(val('dcm'))||0,used:0,start:val('dcs'),end:val('dce'),active:true};if(!x.code||!x.value)return toast('الكود والقيمة مطلوبان');if((await req('discountCodes')).some(d=>d.code===x.code))return toast('الكود موجود بالفعل');await put('discountCodes',x);closeModal();toast('تم حفظ كود الخصم');render()}
async function discountCodeDelete(id){let x=(await req('discountCodes')).find(x=>x.id===id);if(!x||!confirm('حذف كود الخصم؟'))return;await new Promise((res,rej)=>{let q=db.transaction('discountCodes','readwrite').objectStore('discountCodes').delete(id);q.onsuccess=res;q.onerror=()=>rej(q.error)});render()}
async function saveOpenings(){let x={id:'finance',drawerOpening:Number(val('open_drawer'))||0,walletOpening:Number(val('open_wallet'))||0,instapayOpening:Number(val('open_instapay'))||0};await put('settings',x);toast('تم حفظ أرصدة البداية');render()}

async function autoBackupSnapshot(){let key='autoBackup-'+today(),existing=(await req('settings')).find(x=>x.id===key);if(existing)return;let data={version:12,exportedAt:now(),app:'MAGHRABY STORE AUTO BACKUP'};for(const st of stores){let rows=await req(st);if(st==='settings')rows=rows.filter(x=>!String(x.id).startsWith('autoBackup-'));data[st]=rows}await put('settings',{id:key,date:today(),data});let snaps=(await req('settings')).filter(x=>String(x.id).startsWith('autoBackup-')).sort((a,b)=>String(b.id).localeCompare(String(a.id)));for(const x of snaps.slice(30))await new Promise((res,rej)=>{let q=db.transaction('settings','readwrite').objectStore('settings').delete(x.id);q.onsuccess=res;q.onerror=()=>rej(q.error)})}
async function backup(){let data={version:12,exportedAt:now(),app:'MAGHRABY STORE FINAL COMPLETE'};for(const st of stores){let rows=await req(st);if(st==='settings')rows=rows.filter(x=>!String(x.id).startsWith('autoBackup-'));data[st]=rows}let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));a.download='MAGHRABY_STORE_BACKUP_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('تم إنشاء نسخة احتياطية كاملة')}
async function restore(file){if(!file)return;try{let d=JSON.parse(await file.text());if(!d||!d.version)return toast('ملف النسخة غير صالح');if(!confirm('استرجاع النسخة سيستبدل البيانات الحالية بالكامل. هل أنت متأكد؟'))return;const tx=db.transaction(stores,'readwrite');for(const st of stores){let os=tx.objectStore(st);os.clear();for(const x of (d[st]||[]))os.put(x)}await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error||new Error('restore failed'));tx.onabort=()=>rej(tx.error||new Error('restore aborted'))});toast('تم استرجاع النسخة واستبدال البيانات الحالية بالكامل');location.reload()}catch(e){console.error(e);toast('ملف النسخة غير صالح أو تعذر استرجاعه')}}
async function log(action,data){await put('audit',{id:uid(),date:now(),action,data})}
function modal(t,b){$('mt').textContent=t;$('mb').innerHTML=b;$('modal').classList.remove('hidden')}function closeModal(){$('modal').classList.add('hidden')}$('mc').onclick=closeModal;
function toast(t){let x=document.createElement('div');x.className='toast';x.textContent=t;$('toast').appendChild(x);setTimeout(()=>x.remove(),2300)}
boot();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});